INSERT INTO app.question_families(id,exam_version_id,objective_id,family_key) VALUES ('00000000-0000-4000-8000-000000000200','00000000-0000-4000-8000-000000000020','00000000-0000-4000-8000-000000000031','retained-files');
INSERT INTO app.question_versions(id,family_id,exam_version_id,revision,prompt_markdown,source_url) VALUES ('00000000-0000-4000-8000-000000000300','00000000-0000-4000-8000-000000000200','00000000-0000-4000-8000-000000000020',1,'What is needed to query an older table version?','https://learn.microsoft.com/en-us/azure/databricks/tables/history');
INSERT INTO app.question_options VALUES ('00000000-0000-4000-8000-000000000300','A','Its retained log and data files',1);
INSERT INTO app.question_options VALUES ('00000000-0000-4000-8000-000000000300','B','Only the latest table version',2);
INSERT INTO app.question_options VALUES ('00000000-0000-4000-8000-000000000300','C','Only its history entry',3);
INSERT INTO app.question_options VALUES ('00000000-0000-4000-8000-000000000300','D','A new table name',4);
INSERT INTO private.correct_options VALUES ('00000000-0000-4000-8000-000000000300','A');
INSERT INTO private.question_explanations(question_version_id,rationale_markdown,reviewed_notes) VALUES ('00000000-0000-4000-8000-000000000300','An older version needs its corresponding log and data files.','Illustrative draft; independent subject-matter review not yet performed.');
INSERT INTO app.lesson_question_pool VALUES ('00000000-0000-4000-8000-000000000050','00000000-0000-4000-8000-000000000020','00000000-0000-4000-8000-000000000200',1);
INSERT INTO app.question_families(id,exam_version_id,objective_id,family_key) VALUES ('00000000-0000-4000-8000-000000000201','00000000-0000-4000-8000-000000000020','00000000-0000-4000-8000-000000000031','history-versus-data');
INSERT INTO app.question_versions(id,family_id,exam_version_id,revision,prompt_markdown,source_url) VALUES ('00000000-0000-4000-8000-000000000301','00000000-0000-4000-8000-000000000201','00000000-0000-4000-8000-000000000020',1,'Does table history guarantee that old data is still available?','https://learn.microsoft.com/en-us/azure/databricks/tables/history');
INSERT INTO app.question_options VALUES ('00000000-0000-4000-8000-000000000301','A','No. Required files may be removed.',1);
INSERT INTO app.question_options VALUES ('00000000-0000-4000-8000-000000000301','B','Yes. History keeps every data file.',2);
INSERT INTO app.question_options VALUES ('00000000-0000-4000-8000-000000000301','C','Only if the table gets larger.',3);
INSERT INTO app.question_options VALUES ('00000000-0000-4000-8000-000000000301','D','Yes. Old versions last forever.',4);
INSERT INTO private.correct_options VALUES ('00000000-0000-4000-8000-000000000301','A');
INSERT INTO private.question_explanations(question_version_id,rationale_markdown,reviewed_notes) VALUES ('00000000-0000-4000-8000-000000000301','History is not a data archive. Cleanup can remove files an older version needs.','Illustrative draft; independent subject-matter review not yet performed.');
INSERT INTO app.lesson_question_pool VALUES ('00000000-0000-4000-8000-000000000050','00000000-0000-4000-8000-000000000020','00000000-0000-4000-8000-000000000201',2);
INSERT INTO app.question_families(id,exam_version_id,objective_id,family_key) VALUES ('00000000-0000-4000-8000-000000000202','00000000-0000-4000-8000-000000000020','00000000-0000-4000-8000-000000000032','vacuum-purpose');
INSERT INTO app.question_versions(id,family_id,exam_version_id,revision,prompt_markdown,source_url) VALUES ('00000000-0000-4000-8000-000000000302','00000000-0000-4000-8000-000000000202','00000000-0000-4000-8000-000000000020',1,'What can VACUUM remove from a Delta table?','https://learn.microsoft.com/en-us/azure/databricks/sql/language-manual/delta-vacuum');
INSERT INTO app.question_options VALUES ('00000000-0000-4000-8000-000000000302','A','Every row in the latest version',1);
INSERT INTO app.question_options VALUES ('00000000-0000-4000-8000-000000000302','B','Unused data files beyond the retention threshold',2);
INSERT INTO app.question_options VALUES ('00000000-0000-4000-8000-000000000302','C','Only the table name',3);
INSERT INTO app.question_options VALUES ('00000000-0000-4000-8000-000000000302','D','Only active streaming checkpoints',4);
INSERT INTO private.correct_options VALUES ('00000000-0000-4000-8000-000000000302','B');
INSERT INTO private.question_explanations(question_version_id,rationale_markdown,reviewed_notes) VALUES ('00000000-0000-4000-8000-000000000302','VACUUM can remove unused data files after the retention threshold.','Illustrative draft; independent subject-matter review not yet performed.');
INSERT INTO app.lesson_question_pool VALUES ('00000000-0000-4000-8000-000000000050','00000000-0000-4000-8000-000000000020','00000000-0000-4000-8000-000000000202',3);
INSERT INTO app.question_families(id,exam_version_id,objective_id,family_key) VALUES ('00000000-0000-4000-8000-000000000203','00000000-0000-4000-8000-000000000020','00000000-0000-4000-8000-000000000031','version-query');
INSERT INTO app.question_versions(id,family_id,exam_version_id,revision,prompt_markdown,source_url) VALUES ('00000000-0000-4000-8000-000000000303','00000000-0000-4000-8000-000000000203','00000000-0000-4000-8000-000000000020',1,'Which query requests version 12 of sales?','https://learn.microsoft.com/en-us/azure/databricks/tables/history');
INSERT INTO app.question_options VALUES ('00000000-0000-4000-8000-000000000303','A','SELECT * FROM sales VERSION AS OF 12',1);
INSERT INTO app.question_options VALUES ('00000000-0000-4000-8000-000000000303','B','SELECT * FROM sales ONLY VERSION 12',2);
INSERT INTO app.question_options VALUES ('00000000-0000-4000-8000-000000000303','C','RESTORE SELECT sales VERSION 12',3);
INSERT INTO app.question_options VALUES ('00000000-0000-4000-8000-000000000303','D','SELECT HISTORY(12) FROM sales',4);
INSERT INTO private.correct_options VALUES ('00000000-0000-4000-8000-000000000303','A');
INSERT INTO private.question_explanations(question_version_id,rationale_markdown,reviewed_notes) VALUES ('00000000-0000-4000-8000-000000000303','VERSION AS OF selects a historical table version when its required files remain available.','Illustrative draft; independent subject-matter review not yet performed.');
INSERT INTO app.lesson_question_pool VALUES ('00000000-0000-4000-8000-000000000050','00000000-0000-4000-8000-000000000020','00000000-0000-4000-8000-000000000203',4);
INSERT INTO app.question_families(id,exam_version_id,objective_id,family_key) VALUES ('00000000-0000-4000-8000-000000000204','00000000-0000-4000-8000-000000000020','00000000-0000-4000-8000-000000000031','retention-settings');
INSERT INTO app.question_versions(id,family_id,exam_version_id,revision,prompt_markdown,source_url) VALUES ('00000000-0000-4000-8000-000000000304','00000000-0000-4000-8000-000000000204','00000000-0000-4000-8000-000000000020',1,'A team needs a 30-day-old snapshot. What should it check?','https://learn.microsoft.com/en-us/azure/databricks/tables/history');
INSERT INTO app.question_options VALUES ('00000000-0000-4000-8000-000000000304','A','Only current storage capacity',1);
INSERT INTO app.question_options VALUES ('00000000-0000-4000-8000-000000000304','B','Only the latest version number',2);
INSERT INTO app.question_options VALUES ('00000000-0000-4000-8000-000000000304','C','Both log and data file retention',3);
INSERT INTO app.question_options VALUES ('00000000-0000-4000-8000-000000000304','D','Only the table owner',4);
INSERT INTO private.correct_options VALUES ('00000000-0000-4000-8000-000000000304','C');
INSERT INTO private.question_explanations(question_version_id,rationale_markdown,reviewed_notes) VALUES ('00000000-0000-4000-8000-000000000304','Both retention settings matter when planning access to older versions.','Illustrative draft; independent subject-matter review not yet performed.');
INSERT INTO app.lesson_question_pool VALUES ('00000000-0000-4000-8000-000000000050','00000000-0000-4000-8000-000000000020','00000000-0000-4000-8000-000000000204',5);
